CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, first_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', organization text NOT NULL DEFAULT '', current_city text NOT NULL DEFAULT '', home_city text NOT NULL DEFAULT '', sms_consent boolean NOT NULL DEFAULT false, break_start date, break_end date, availability text NOT NULL DEFAULT '', interests text[] NOT NULL DEFAULT '{}', reminder_preferences text[] NOT NULL DEFAULT '{}', onboarding_complete boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own profile" ON public.profiles FOR ALL TO authenticated USING (auth.uid()=id) WITH CHECK (auth.uid()=id);
CREATE FUNCTION public.create_beni_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES (NEW.id); RETURN NEW; END; $$;
CREATE TRIGGER beni_profile_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_beni_profile();
CREATE TABLE public.plans_uploaded (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, file_name text NOT NULL, storage_path text NOT NULL, status text NOT NULL DEFAULT 'uploaded' CHECK(status IN ('uploaded','processing','ready','failed')), provider text, plan_name text, plan_type text, deductible text, out_of_pocket_max text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.plans_uploaded TO authenticated; GRANT ALL ON public.plans_uploaded TO service_role;
ALTER TABLE public.plans_uploaded ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own plans" ON public.plans_uploaded FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.benefits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, plan_id uuid NOT NULL REFERENCES public.plans_uploaded(id) ON DELETE CASCADE, name text NOT NULL, category text NOT NULL, coverage_status text NOT NULL, cost text, visit_limit integer, restrictions text, source_page integer NOT NULL CHECK(source_page>0), description text, hidden_perk boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.benefits TO authenticated; GRANT ALL ON public.benefits TO service_role;
ALTER TABLE public.benefits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own documented benefits" ON public.benefits FOR SELECT TO authenticated USING(auth.uid()=user_id);
CREATE TABLE public.visits (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, benefit_id uuid REFERENCES public.benefits(id) ON DELETE SET NULL, visit_date date NOT NULL, confirmed boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.visits TO authenticated; GRANT ALL ON public.visits TO service_role;
ALTER TABLE public.visits ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own visits" ON public.visits FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND confirmed=true);
CREATE TABLE public.providers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, city text, contact text, booking_url text, network_verified boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.providers TO authenticated; GRANT ALL ON public.providers TO service_role;
ALTER TABLE public.providers ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own providers" ON public.providers FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.calendar_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, starts_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'hold' CHECK(status IN('hold','planned','provider_confirmed')), user_confirmed boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.calendar_events TO authenticated; GRANT ALL ON public.calendar_events TO service_role;
ALTER TABLE public.calendar_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own calendar" ON public.calendar_events FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE TABLE public.messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, direction text NOT NULL CHECK(direction IN('incoming','outgoing')), body text NOT NULL, channel text NOT NULL DEFAULT 'demo' CHECK(channel IN('demo','sms','imessage')), delivery_status text NOT NULL DEFAULT 'demo', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.messages TO authenticated; GRANT ALL ON public.messages TO service_role;
ALTER TABLE public.messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own messages" ON public.messages FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id AND channel='demo' AND delivery_status='demo');
CREATE TABLE public.reminders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, title text NOT NULL, remind_at timestamptz, status text NOT NULL DEFAULT 'pending');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.reminders TO authenticated; GRANT ALL ON public.reminders TO service_role;
ALTER TABLE public.reminders ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own reminders" ON public.reminders FOR ALL TO authenticated USING(auth.uid()=user_id) WITH CHECK(auth.uid()=user_id);
CREATE POLICY "Upload own insurance PDF" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='insurance-plans' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name))='pdf');
CREATE POLICY "Read own insurance PDF" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='insurance-plans' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY "Delete own insurance PDF" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='insurance-plans' AND (storage.foldername(name))[1]=auth.uid()::text);
ALTER PUBLICATION supabase_realtime ADD TABLE public.messages,public.benefits,public.visits,public.calendar_events;
CREATE INDEX plans_user_idx ON public.plans_uploaded(user_id); CREATE INDEX benefits_user_idx ON public.benefits(user_id); CREATE INDEX messages_user_idx ON public.messages(user_id);